CREATE TABLE NodaTimeRoundTrip (Id NUMBER(19) PRIMARY KEY, InstantValue TIMESTAMP NULL, LocalDateValue DATE NULL, LocalDateTimeValue TIMESTAMP NULL, LocalTimeValue INTERVAL DAY TO SECOND NULL, OffsetDateTimeValue TIMESTAMP WITH TIME ZONE NULL, OffsetValue NUMBER(10) NULL, DurationValue NUMBER(19) NULL, PeriodValue VARCHAR2(176) NULL, CalendarValue VARCHAR2(50) NULL, ZoneValue VARCHAR2(50) NULL)
